#!/usr/bin/env bash
# eager re-eval (run.py eval is eager now: the compiled no_grad eval gave wrong masks) of each run's FINAL checkpoint -> runs/<run>-reeval/logs-rank0.txt
# --eval-only takes transformer3's CURRENT defaults, not args.json: every arch/loss knob is passed explicitly from runs/<run>/args.json
# (knobs newer than a run = the current default = the old code's behaviour); train-only knobs (augs, token dropout) don't matter for eval.
# all strict-load checked on cpu (2026-11-02). skipped: std-samplez-v1 (pre-commit transformer3: --norm sample_z / --pos rope / --box-head, encoder.empty5_* buffers -> strict load fails)
# table: .venv/bin/python <scratchpad>/reeval_table.py <runs>
cd /home/ethantu/workspace/good-vibrations
PY=.venv/bin/python
export PYTHONUTF8=1
ev() { local run=$1 ck=$2; shift 2
  echo "=== $run ($ck) $(date)"
  $PY src9/run.py --model transformer3 --eval-only 1 --checkpoint-path runs/$run/checkpoints/$ck --run-name $run-reeval --wandb 0 --compile 0 "$@" 2>&1 | tee runs/$run-reeval.log
}
ev base300-v1 ep300-ba3000-rank0.pt --height 64 --width 64 --bins-per-band 65 --d 256 --heads 8 --freq-layers 4 --laser-layers 8 --latent-dim 512 --readout per --maskae "" --heatmap-w 0.0 --mask-loss bce_dice --dice-w 0.5 --objrecall-w 0.0 --boundary-w 0.0 --gan-w 0.0 --norm sample --log-mag 0 --window tukey --eval-batch-size 108 --microbatch 128
